def _decode(b64: str) -> pd.DataFrame:
    """Reverse the embed step: base64-decode, zlib-decompress, then parse as CSV.
    This is how the app carries its own data without any external file — the
    two _DAILY_B64 / _HOURLY_B64 strings above ARE daily_merged.csv / hourly_merged.csv,
    just compressed so the .py file stays a reasonable size."""
    raw = zlib.decompress(base64.b64decode(b64.strip()))
    return pd.read_csv(io.BytesIO(raw))


